16	func (d *DB) CreateMemo(ctx context.Context, create *store.Memo) (*store.Memo, error) {
17		fields := []string{"`uid`", "`creator_id`", "`content`", "`visibility`", "`payload`"}
18		placeholder := []string{"?", "?", "?", "?", "?"}
19		payload := "{}"
20		if create.Payload != nil {
21			payloadBytes, err := protojson.Marshal(create.Payload)
22			if err != nil {
23				return nil, err
24			}
25			payload = string(payloadBytes)
26		}
27		args := []any{create.UID, create.CreatorID, create.Content, create.Visibility, payload}
28	
29		// Add custom timestamps if provided
30		if create.CreatedTs != 0 {
31			fields = append(fields, "`created_ts`")
32			placeholder = append(placeholder, "?")
33			args = append(args, create.CreatedTs)
34		}
35		if create.UpdatedTs != 0 {
36			fields = append(fields, "`updated_ts`")
37			placeholder = append(placeholder, "?")
38			args = append(args, create.UpdatedTs)
39		}
40	
41		stmt := "INSERT INTO `memo` (" + strings.Join(fields, ", ") + ") VALUES (" + strings.Join(placeholder, ", ") + ") RETURNING `id`, `created_ts`, `updated_ts`, `row_status`"
42		if err := d.db.QueryRowContext(ctx, stmt, args...).Scan(
43			&create.ID,
44			&create.CreatedTs,
45			&create.UpdatedTs,
46			&create.RowStatus,
47		); err != nil {
48			return nil, err
49		}
50	
